INSERT INTO `artist` VALUES (1,'Ksb Muzic','Ksb Muzic это взрывная панк-рок группа, которая превращает сцену в хаос и анархию. Их музыка – это протест против скуки, фальши и серости, а тексты – крик души о свободе, борьбе и вечном бунте. Громкие гитарные риффы, бешеный ритм и вокал, пробирающий до мурашек – все это делает их выступления незабываемыми. Они не пытаются понравиться – они просто делают, что хотят, и заставляют каждого почувствовать настоящую энергию панка.','ксб музик avatar_artist.jpg','ксб музик back_image_arist.jpeg','#691717'),(2,'Lovv66','Иван Шабашов, известный под псевдонимом Lovv66, — российский рэп-исполнитель родом из Брянска. В юности испытал множество трудностей, связанных со смертью матери, в том числе проблемы с учёбой, алкоголем и законом. Шабашов был вынужден неоднократно переезжать в другие города и в итоге обосновался в Ростове (Великом).','Lovv66 avatar_artist.jpg','Lovv66 back_image_arist.jpg','#BD5B51'),(3,'GONE.Fludd','Gone.Fludd является порождением эпохи «хайповых» подростков, умеющих выстроить карьеру и заработать первый миллион, ещё не окончив школы (или, на худой конец, института). В 2013-м Gone.Fludd, или Александр Смирнов, создал с одноклассниками музыкальное комьюнити Sabbat Cult. 2016 год оказался плодотворным: выпуск трёх альбомов совместно с Iroh, M00nchild и Lottery Billz. Популярность поприветствовала Александра после выхода альбома Boys don’t cry. Именно в него вошёл хит «Кубик льда», растопивший слушателей текстом, построенным на провокационной метафоре. Песня «Мамбл» из этого же альбома ещё больше подогрела интерес: за быстрым речитативом проглатываются слова, но, вслушавшись, понимаешь, почему Gone.Fludd так спешит: 70% песни — «сниженная» лексика. «Кто твой папочка, ночная бабочка?» — пожалуй, самая безобидная строчка. 2018 год — расцвет творчества и пик популярности. Успех сольного альбома «Суперчуитс» «подсластил» лирику Gone.Fludd. Оказывается, посыл текстов у артиста может быть добрее — в песне «Сахарный человек» Смирнов поэтично запевает: «Помоги сдуть мне с мечты эту пыль». Хип-хоп исполнитель Gone.Fludd — это симбиоз грубости, нежности и отличного ритма, под который качает даже тогда, когда у особо «сахарных» вянут уши.','GONE.Fludd avatar_artist.jpg','GONE.Fludd back_image_arist.jpg','#BD5B51'),(4,'Мэйби Бэйби','Девочка с яркими синими волосами — так можно легко узнать Мэйби Бэйби. Виктория Лысюк (настоящее имя артистки) родилась в белорусском городе Жабинка, там же успешно училась в школе и была вокалисткой в местной рок-группе «Зеленые педали». В 2018 году, после переезда в Петербург и окончания вуза, Виктория вступила в российскую группу «Френдзона», куда её пригласил Владимир Галат. В том же году появляется сольный проект Мэйби Бэйби и сингл «Аскорбинка», клип к которому остается одним из самых популярных. Любовь певицы к танцам, косплею и кей-попу отражается в творчестве — её клипы яркие и динамичные, а кукольный образ добавляет детской непосредственности. Тексты «Френдзоны» и Мэйби Бэйби находят живой отклик среди молодёжи: в песнях описаны трудности взросления, токсичная атмосфера учебных заведений, зависимости и запутанность в дружеских и любовных отношениях. После распада «Френдзоны» в 2022 году Мэйби Бэйби выступает с первым сольным туром, разрывает интернет диссом на Инстасамку и выпускает первый полноформатный альбом «Мэйбилэнд». Певица показывает себя не только как поп-, но и как рэп-исполнительница.','Мэйби Бэйби avatar_artist.jpg','Мэйби Бэйби back_image_arist.jpg','#E91E63'),(5,'Billy’s Band','Музыкант Андрей Резников и патологоанатом в прошлом Билли Новик — основатели блюз-джаз-коллектива Billy’s Band. Познакомились они в клубе, где Резников был арт-директором, а Новик осваивал музыкальную сцену. Большое влияние на Billy’s Band оказал американский певец Том Уэйтс. На заре карьеры музыканты выступали с кавер-версиями его песен. Позднее артисты пришли к собственной музыке и стилю, который охарактеризовали как «романтический алкоджаз». Началом карьеры артистов можно считать 2001 год: после первого тура в Германию музыканты стали чаще выступать в клубах, а также на крупных мероприятиях в России и за границей. Творческая деятельность группы не ограничивается сольными концертами и выступлениями на популярных фестивалях. Участники бенда создали две театрализованные программы: Being Tom Waits и «Блюз в голове». Первая программа была основана на песнях Уэйтса, вторая — на собственных композициях. Представления проходили на известных театральных сценах. Также у вокалиста Билли Новика есть своя концертная программа, посвящённая творчеству Егора Летова. Сейчас в группе три участника: несменные Новик (контрабас) и Резников (гитара), а также Михаил Жидких (саксофон, ударные и пианино).','Billy’s Band avatar_artist.jpg','Billy’s Band back_image_arist.jpg','#4058C4'),(6,'Лампабикт','Лампабикт – инди-группа, создающая атмосферную музыку на стыке меланхолии и светлого безумия. Их звук — это сочетание глубокой лирики, воздушных гитарных рифов и ритмов, пробуждающих воспоминания о теплых ночах и странных снах. Каждый трек — это отдельная история, где чувства важнее слов, а мелодии остаются в сердце надолго. Лампабикт — это музыка, которая звучит внутри тебя даже после того, как песни закончились.','лампабикт avatar_artist.jpg','лампабикт back_image_arist.jpg','#4CAF50'),(7,'Polnalyubvi','Марина Демещенко (polnalyubvi) — молодая российская певица. Уроженка Чукотки, в тринадцатилетнем возрасте она оказалась в Санкт-Петербурге, где тремя годами позже начала свою музыкальную карьеру. Впрочем, первых поклонников Марина привлекла не музыкой — в подростковом возрасте девушка была моделью. Параллельно с фотографиями Демещенко выкладывала каверы на разные песни. Вскоре она начала записывать треки собственного производства и давать небольшие концерты в клубах и квартирах. Свой дебютный альбом под названием «V» polnalyubvi презентовала ещё во время учёбы в старшей школе. Большой успех пришёл к певице с новым десятилетием: пластинка «Сказки лесной нимфы» завирусилась в соцсети TikTok, а песни «Девочка и море» и «Кометы» стали настоящими хитами. Благодаря завораживающей атмосфере своих треков, представляющих собой смесь попа, альтернативы и элементов фолк-музыки, polnalyubvi всего за пару лет влюбила в себя сотни тысяч интернет-пользователей. Певица начала регулярно появляться на музыкальных ТВ-шоу и ездить в туры по городам России.','Polnalyubvi avatar_artist.jpg','Polnalyubvi back_image_arist.jpg','#9A6659'),(8,'Zoloto','Владимир Золотухин, он же Zoloto, — популярный российский и казахстанский певец. Уроженец киргизского города Кант, Владимир вырос в Алматы, а уже после совершеннолетия оказался в Москве, где и добился известности. Впрочем, музыкальную карьеру Золотухин начал в 2009 году, ещё до переезда в столицу России: он стал основателем и лидером группы «Cardio Beat». В 2015 году рок-коллектив выступил на российском шоу талантов «Главная сцена», однако не прошёл дальше четвертьфинала. Псевдоним Zoloto Владимир выбрал уже после ухода из группы — его желание экспериментировать с жанрами музыки не нашло большого отклика у других членов коллектива. Сольный проект исполнителя принёс ему популярность далеко не сразу. Лишь второй альбом Zoloto «8 месяцев в Вегасе» (2019) привлёк к музыканту большое внимание. Интересное смешение рока с акустическим инструменталом и элементами хип-хопа было высоко оценено слушателями, а композиция «Улицы ждали» стала настоящим хитом. В дискографии Zoloto можно найти много любопытного, например, записанный на концерте лайв-альбом «Live in Moscow 2021» и песню-кавер «Я ненавижу свет» на стихи поэта Осипа Мандельштама.','Zoloto avatar_artist.jpg','Zoloto back_image_arist.png','#9A6659'),(9,'7Б','Российская рок-группа. На Яндекс Афише опубликована актуальная информация о музыкальном исполнителе 7Б. Яндекс Афиша работает только c официальными партнерами и публикует проверенные новости о событиях и датах всех выступлений. Мы систематически публикуем актуальный перечень концертов, а так же вы можете ознакомиться со сведениями об артисте 7б, творчестве и наградах. Подпишитесь на уведомления, и вы сможете приобрести билеты и узнать цены на проходящие мероприятия.','7Б avatar_artist.jpg','7Б back_image_arist.jpg','#D32F2F'),(10,'Кипелов','Диплом музыкальной школы по классу «баян», ВИА «Крестьянские дети», «Лейся, песня» и «Поющие сердца» — это этапы карьеры звезды российского хеви-метал Валерия Кипелова. В «Поющих сердцах» Кипелов и познакомился с основателями «Арии» Владимиром Холстининым и Аликом Грановским. Валерий стал первым вокалистом группы и пережил с «Арией» все взлёты и падения — от статуса фронтмена главного хард-рок коллектива СССР до работы ночным сторожем в лихие девяностые. В 1994 году Кипелов выступал с группой «Мастер», состоящей из бывших участников «Арии», и рассорился с Холстининым, однако представители Moroz Records, выпускающей альбомы «Арии», объявили музыкантам, что без Кипелова новый альбом они не запишут. Валерий вернулся в студию, а затем и на сцену в составе «Арии». Статус кво продержался до 2001 года, когда Кипелов ушёл окончательно. При участии Сергея Маврина, игравшего в «Арии» с 1987 по 1995 год, была создана группа «Кипелов». Пока оставшиеся «арийцы» пытались вписать в свою картину мира вокалиста Артура Беркута, «Кипелов» поехал в тур по России с песнями «Арии». На этих концертах был записан первый официальный концертный альбом группы «Путь наверх», в 2005 группа выпустила полноценный студийный альбом «Реки времён». Следующей записи поклонники ждали шесть лет, «Жить вопреки» вышел в 2011, следующий — «Звёзды и кресты» — ещё через шесть лет. Кипелов вообще не балует слушателей регулярными новинками, он работает в своё удовольствие и по-прежнему несёт в массы старый добрый хеви-метал.','Кипелов avatar_artist.jpg','Кипелов back_image_arist.jpg','#8A3838'),(11,'Пикник','Первый состав группы «Пикник» собрался в 1978 году в Ленинградском политехническом училище — и в их самобытном творчестве ещё не было инфернальности, готичности и эффектности нынешнего «Пикника». Возможно, потому что не было Эдмунда Шклярского. Шклярский появился в составе только в 1981 — и сразу занял позицию лидера и фронтмена группы. Первый альбом был записан в 1982 году, «Пикник» приняли в Ленинградский рок-клуб и вроде бы жизнь наладилась, но через два года музыканты перессорились. В «Пикнике» остались только Шклярский и гитарист Александр Савельев. Дуэт, при поддержке сессионных музыкантов, записал второй альбом — «Танец волка», — который и явил миру тот «Пикник», который знаком меломанам, мрачный, эстетский и оригинальный. Конечно, линии партии эта музыка не соответствовала, но «Пикнику» удавалось гастролировать, а в 1988 году рокеры даже записали официальную пластинку на «Мелодии». В девяностых группа продолжала выступать, ездить в туры и записывать новый материал, но настоящий прорыв случился только в конце века — когда Шклярский всерьёз взялся за шоу. Рядом с музыкантами на сцене появились хитроумные странные приборы и инструменты, акробаты и танцоры, «Пикник» не скупился на декорации и пиротехнику. С тех пор каждое выступление группы — это мистерия, уникальное событие, а каждая концертная программа — срежиссированное грандиозное представление с участием профессиональных актёров из дружественных театров. Песни соответствуют уровню шоу — творчество «Пикника» состоит из множества хитроумных жанровых сочетаний от симфонического арт-рока до фолка и даже нью-вейва.','Пикник avatar_artist.jpg','Пикник back_image_arist.jpg','#D32F2F'),(12,'Чиж & Co','В насыщенной карьере Сергея Чигракова — первые шаги по большой сцене с «Разными людьми» Чернецкого, сотрудничество с музыкантами «Аквариума» и «ДДТ», участие в капустниках вроде «Митьковских песен» наравне со звёздами российского рока, альбом «Chizh & Blues Company», записанный с американскими блюзменами. При этом основной период творческой активности Чижа пришёлся на 90-е годы прошлого века: последний полноценный лонгплей группы с новым материалом вышел в 1999-м, а второй сольный — знаменитый «Гайдном буду!», где музыкант самостоятельно спел и сыграл на всех инструментах, — в 2001-м. Слухи о том, что Чиж и компания заняты обновлением репертуара, ходят с 2019-го, и есть вероятность, что новые песни прозвучат на ближайших концертах. Как бы то ни было, элегантный, слегка старомодный блюз-рок Чиграков не променяет ни на что, а в концертной программе «Чиж и ко» любой слушатель, даже не являясь фанатом, узнает множество хитов. Песни Чигракова, такие как «Вечная молодость», «Полонез», «Перекрёсток», «О любви», давно вышли в народ: они в эфирах радиостанций любого формата, их пели под гитару, а теперь заказывают в караоке, наконец, их обязательно хором поют зрители на выступлениях группы.','Чиж & Co avatar_artist.jpg','Чиж & Co back_image_arist.jpg','#D32F2F'),(13,'Крематорий','«Крематорий» — ветераны российской рок-сцены. Коллектив образовался в 1983 году, лидером группы был и есть по сегодняшний день Армен Григорян. «Крематорий» начинал свой творческий путь с небольших музыкальных площадок: артисты проводили квартирники в Москве. Постепенно на их концерты стало приходить всё больше желающих. В 1985-м вышел альбом «Иллюзорный мир». Этот сборник принёс музыкантам всесоюзную славу. Начались туры в другие города Советского Союза. Позже уже известные в рок-кругах музыканты выступали на площадках Германии, США и Израиля. Тексты песен «Крематория» отражают особый взгляд музыкантов на мир, фронтмен Армен Григорян — автор большей части «крематорского» репертуара. В песнях часто затрагиваются философские и религиозные темы. Коллектив сложно представить не только без неизменного вокалиста в чёрной шляпе, но и без скрипки. Этот музыкальный инструмент придаёт року «Крематория» особый колорит. Несмотря на приличный творческий стаж, гастрольный график группы по-прежнему плотный: они продолжают выступать перед зрителями не только в столице, но и в других городах России.','Крематорий avatar_artist.jpg','Крематорий back_image_arist.jpg','#D32F2F'),(14,'Варвара Визбор','Внучка известного советского барда Юрия Визбора стала популярной после того, как появилась на шоу «Голос». Прослушивание Варвара Визбор не прошла — зато полюбилась миллионам зрителей. До перезапуска музыкальной карьеры Визбор училась в Щукинском училище и пела в мелких московских джаз-барах; сейчас её выступления с собственной группой можно увидеть на известных площадках и сценах крупных фестивалей. Голос певицы часто сравнивают со звоном ручья — или вовсе называют глотком свежего воздуха на современной эстраде. К слову, её концертные программы — это действительно нечто необычное: бардовская песня и музыка из советских кинофильмов в соул- и поп-обработке. Визбор признавалась в интервью журналу Hello, что эстетика авторской песни никогда не была ей близка. Но, кажется, её творческие эксперименты с классикой одобряют и поклонники, и звёздные коллеги. Так, в 2016 году рэпер L’One выпустил трек «Якутяночка» с участием Варвары. Позднее с ней также записывались другие музыканты — Uma2rman и «Марсу нужны любовники»','Варвара Визбор avatar_artist.jpg','Варвара Визбор back_image_arist.jpg','#9A6659'),(15,'Слава КПСС','Российский хип-хоп-исполнитель Вячеслав Машнов, известный под огромным количеством псевдонимов — Слава КПСС, Гнойный, Соня Мармеладова, Валентин Дядька, Слава Карелин и т.д., — родился в 1990 году в Хабаровске. Музыкальная карьера рэпера началась в десятые: 2012 годом датирован его первый EP «Ежемесячные». Спустя небольшое время после дебютного релиза Вячеслав переехал из родного Хабаровска в Санкт-Петербург. Огромную популярность Слава КПСС приобрёл как участник рэп-баттлов на питерских баттл-площадках. Самый известный словесный поединок рэпера — против Мирона Фёдорова (Oxxxymiron; признан иностранным агентом) — собрал более 50 миллионов просмотров. Параллельно Слава КПСС продолжал выпускать музыку — в 2017 году вышел его дебютный лонгплей «Солнце мёртвых». Вячеслав известен своими резкими и провокационными высказываниями о других музыкантах, общественных ценностях и политике. В его дискографии можно найти большое количество сатирических песен, высмеивающих коллег по цеху. В 2023 году Слава КПСС выпустил альбом «Горгород 2», пародийный сиквел «Горгорода», попавший в топ-10 российского чарта Apple Music. Пластинки «Россия34» и «Россия24» (обе — 2024) — также получились суперуспешными. Осенью того же года Слава КПСС анонсировал большой тур по 20 городам России.','Слава КПСС avatar_artist.jpg','Слава КПСС back_image_arist.jpg','#BD5B51'),(16,'Boulevard Depo','Артём Шатохин, известный как Boulevard Depo (Бульвар Депо) — экс-художник граффити и живая легенда российского хип-хопа. Музыкой Артём начал заниматься ещё в родном городе — Уфе, переезд в Санкт-Петербург в 2009 году помог Boulevard Depo в продвижении музыкальной карьеры. После двух микстейпов, принесших артисту сравнительную популярность, Артём основывает музыкальное объединение YungRussia, через которое прошло огромное количество звёзд отечественной хип-хоп музыки. Выстреливший в 2015 году трек Champagne squirt, записанный вместе с Глебом Голубиным (Pharaoh), принёс объединению большую популярность перед первым туром по России. На альбоме Otricala того же года Boulevard Depo фитовал с многими звёздными коллегами по YungRussia — от старого уфимского знакомого i61 до Jeembo и Tveth’а. Настоящим хитом стала совместная песня Boulevard Depo и Pharaoh «Пять минут назад», вышедшая за пару месяцев до роспуска объединения YungRussia. С тех пор артист выпустил несколько сольных альбомов и продолжает писать интересные тексты, экспериментировать с музыкой и давать концерты.','Boulevard Depo avatar_artist.jpg','Boulevard Depo back_image_arist.jpg','#BD5B51'),(17,'АК-47','Российская рэп-группа из города Берёзовский Свердловской области, основанная в 2004 году. Названа в честь Автомата Калашникова. Коллектив состоит из двух человек, известных под сценическими псевдонимами: «Витя АК» - Виктор Гостюхин и «Максим АК» - Максим Брылин. На сайте Яндекс Афиша размещена актуальная информация об исполнителе АК-47. Яндекс Афиша сотрудничает только c официальными представителями и дает проверенные сведения о событиях и датах всех выступлений. Мы постоянно обновляем актуальный список мероприятий, а так же вы можете ознакомиться с данными об артисте АК-47, творчестве и премиях. Подпишитесь на уведомления, и вы сможете купить билеты и уточнить график концертов на текущие мероприятия.','АК-47 avatar_artist.jpg','АК-47 back_image_arist.jpg','#BD5B51'),(18,'Паша Техник','Паша Техник — это не просто музыкант, а целый феномен, впитавший в себя дух андерграунда, трэпа и уличной философии. Его творчество — это грязные биты, ироничные тексты, полный хаос и абсолютная свобода самовыражения. Каждое выступление — это смесь трэша, угара и импровизации, где грань между сценой и жизнью стирается. Без цензуры, без шаблонов, без попыток понравиться — только настоящий вайб и поток сознания, который либо врывается в голову, либо оставляет в полном недоумении.','Паша Техник avatar_artist.jpg','Паша Техник back_image_arist.jpg','#BD5B51'),(19,'Thomas Mraz','Российский хип-хоп-исполнитель, музыкант Алмас Гатауллин — уроженец города Уфа. Музыкальный вкус в детстве у него был разносторонний — от «Арии» до Eminem. Даже псевдоним Thomas Mraz — это отсылка к одному из любимых музыкантов Алмаса, Джейсону Томасу Мразу, мультиинструменталисту, существующему на границах жанров соула, альт-рока и даже акустического хип-хопа. Гатауллин тоже избегает банальностей — в его творчестве присутствует солидный разброс от жизнерадостного клубного R’n’B до лихорадочного трэпа. На его альбомах гостят такие известные исполнители, как Pharaoh, ЛСП, Oxxxymiron. Благодаря последнему — а точнее, концертному агентству Booking Machine — Гатауллин выбрался из уфимского андеграунда на настоящий федеральный уровень. Кто-то может сказать, что творчество Thomas Mraz упрощается пропорционально увеличению аудитории, но это вряд ли коммерческий приём — кажется, что Алмас постепенно уходит от эстетских кружев метафор в текстах, оставляя на местах смыслы и аранжируя их боевыми, точёными битами.','Thomas Mraz avatar_artist.jpg','Thomas Mraz back_image_arist.jpg','#BD5B51'),(20,'Каспийский Груз','Одна из самых популярных хип-хоп групп, читающих «пацанский рэп», была образована в 2000-х. Дуэт Анара «ВесЪ» Зейналова и Тимура «Брутто» Одилбекова за почти двадцать лет работы оставил свой след в истории русского рэпа. Музыканты заявили о себе дебютным альбомом «Рингтоны для зоны», который сразу набрал популярность в соцсети. Хоть тексты песен и отсылали к тюремным реалиям, авторы заявляли, что просто создали лирического героя-бандита, который рассказывает о пережитом. Творчество группы заметил Guf, король рэп-сцены того времени. Они записали совместный трек, после чего пришла известность и начались первые успешные гастроли по стране. В ключевом для своей карьеры альбоме «Сторона А / Сторона Б» были как песни от лица лирического героя, так и личное мнение рэперов о семье, любви и жизни. В создании альбома принимали участие известные рэперы. Пластинка вошла в число лучших альбомов 2015 года. После пары сольных альбомов в 2017 году артисты заявили о прекращении музыкальной карьеры, и «Саундтрек к так и не снятому фильму» чуть не стал их последним релизом. Но до сих пор они регулярно радуют фанатов синглами, альбомами и турами.','Каспийский Груз avatar_artist.jpg','Каспийский Груз back_image_arist.jpg','#BD5B51'),(21,'СЛОТ','Группа, играющая в стиле ню-метал и рэпкор, была основана в 2002 году и с тех пор прочно закрепила за собой звание одной из самых популярных альтернативных команд страны. Первый же тур музыкантов захватил более 40 городов. «Слот» и сейчас славится невероятными сроками гастролей и может давать концерты больше года подряд. На фестивалях артисты не раз выступали на одной сцене со звёздами отечественной и зарубежной рок-сцены. Лидер KOЯN поразился их выступлению на Российский альтернативной музыкальной премии и сравнил «Слот» с Evanescence и Linkin Park. Группа постоянно попадает в ротацию и топы российских и иностранных радио. «Слот» любит и сторонние проекты — группа участвовала в создании мюзикла «Всё о Золушке», создала саундтрек «Ангел или демон» для одноименного сериала на СТС. «Слот» легко узнать по характерному женскому экстремальному вокалу. Долгое время постоянной солисткой группы была Дария «Нуки» Ставрович. Певица пришла в группу после второго альбома, с её вокалом он был перезаписан, и «Две войны» получили награду как лучший рок-альбом. В 2024 году Ставрович ушла из группы, в жизни «Слота» наступил новый этап.','СЛОТ avatar_artist.jpg','СЛОТ back_image_arist.jpg','#7FBE6D'),(22,'DK','DK – это культовая группа, ставшая голосом улиц и символом беспечного, но дерзкого образа жизни. Их музыка — это смесь хулиганского рэпа, андеграундного звучания и ироничных текстов, в которых сочетаются абсурд, сарказм и жесткая правда. Они не гонятся за трендами — они сами создают атмосферу, где каждое слово цепляет, а каждый трек становится саундтреком для тех, кто живёт без правил. DK — это не просто музыка, это стиль, настроение и философия уличного хаоса.','DK avatar_artist.jpg','DK back_image_arist.jpg','#7E7B7C'),(23,'U108','U108 – это сырой, честный и бескомпромиссный звук, пропитанный духом андеграунда. Их музыка – это отражение уличной реальности, где смешиваются мрачные биты, холодная атмосфера и тексты, пропитанные болью, сарказмом и рефлексией. Без глянца, без цензуры, без желания кому-то понравиться – только чистая энергия, протест и глубокая меланхолия. U108 – это голос тех, кто остается в тени, но говорит громко.','U108 avatar_artist.jpg','U108 back_image_arist.jpg','#4E71C2'),(24,'Cream Soda','Группа Cream Soda много раз раз экспериментировала со звуком и направлениями. Настоящими хитами стали треки в стиле этно-хауса, полюбившиеся слушателям. В 2016 году трио выпустило свой первый сольный в своей дискографии альбом «Пожар» на лейбле Electronica Records. Диск из 19 композиций стал одним из самых популярных в магазинах электронной музыки. В 2020 году группа получила премию Jager Music Awards в категории «трек года» за песню «Плачу на техно». Артисты обыграли в клипе на эту композицию эпоху коронавируса и ограничений. С 2023 года, после трагической гибели одного из основателей — Дмитрия Свиргунова, трио превратилось в дуэт. Сейчас Cream Soda выступает в составе: Илья Гадаев (второй основоположник группы) и новая вокалистка проекта Алиса Стяжкова. Новый виток в творчестве ознаменовался выходом экспрессивного альбома Internet Friends и полноформатным концертным шоу.','Cream Soda avatar_artist.jpg','Cream Soda back_image_arist.jpg','#746D9B'),(25,'Ирина Круг','Ирина Круг — известная исполнительница песен в жанре шансон. Судьбоносное знакомство с Михаилом Кругом, одним из самых популярных российских шансонье, произошло в челябинском ресторане, в котором Ирина работала официанткой. Михаилу понравилась девушка, и он пригласил её в свою творческую команду на должность костюмера. Через два года после знакомства они поженились. Творческому развитию артистки предшествовали печальные события. В 2002 году Михаил погибает от рук злоумышленников. Коллега певца Владимир Бочаров делает Ирине предложение — исполнить композиции, которые он написал в память о Михаиле. Ирина соглашается, и в 2004 году выходит её альбом «Первая осень разлуки». Это событие можно считать началом карьеры певицы. Далее последовали новые альбомы: как сольные, так и записанные дуэтом с другими исполнителями шансона. За свою творческую карьеру Ирина много раз получала награды «Шансон года». Певицу приглашали на шоу «Привет, Андрей!», она была гостем программы «Судьба человека». Сегодня Ирина Круг продолжает выступать как в России, так и за границей.','Ирина Круг avatar_artist.jpg','Ирина Круг back_image_arist.jpg','#795548'),(26,'Сергей Трофимов','Композитор, автор, поэт и бард, любимый многими исполнитель российской эстрады родился в 1966 году, начал заниматься музыкой с самого детства и окончил Московскую государственную Консерваторию. Артист начинал карьеру в рок-группе, но прошёл длинный путь становления в творчестве и уже много лет пишет в стилях «шансон» и «авторская песня». Известность пришла к нему в 90-х. Сергей стал автором песен для знаменитых российских исполнителей — Каролины, Александра Маршала, Николая Носкова и других, а в 1994 году началась его сольная карьера под псевдонимом Трофим. От лица этого лирического героя Сергей пел о злободневных, каждому понятных вещах. Так родилась серия альбомов «Аристократия помойки», а песни «Гербалайф», «Иномарка», «ТВ-новости», «Бьюсь, как рыба» стали настоящими шлягерами. С 2000-х артист стал уходить от образа Трофима, выступая с всё более серьезными, лиричными песнями. Одной из главных тем его творчества является любовь к Родине, патриотизм. Он несколько раз был награжден премией «Золотой граммофон», стал Заслуженным артистом России, а за свои сборники стихов был принят в члены Союза писателей.','Сергей Трофимов avatar_artist.jpg','Сергей Трофимов back_image_arist.jpg','#795548'),(27,'Лесоповал','«Лесоповал» — один из первых коллективов, начавших исполнять шансон на эстраде. Благодаря жизнеутверждающим текстам, лиричным, запоминающимся мелодиям группа прочно обосновалась в нише российского шансона, а многие песни вошли в «золотой фонд» жанра. Одна из самых известных песен группы «Я куплю тебе дом» была создана буквально по телефону. Михаил Танич в трубку надиктовал стихи, а Сергей Коржуков написал к ним музыкальную композицию. В то время «Лесоповал» только начинал свою творческую карьеру. И песня мгновенно стала хитом. До сих пор зрители в зале на концертах синхронно подхватывают «А белый лебедь на пруду...», при этом мало кто знает настоящее название песни. Название группы «Лесоповал» было выбрано не случайно. Большая часть репертуара коллектива основана на личном опыте Танича: после войны поэт попал в заключение, пережил тюрьму, лагеря и вышел на свободу только после смерти Сталина. Танич ушёл из жизни в 2008-м, но группа осталась. Сейчас музыканты ведут активную концертную деятельность, регулярно ездят в туры. «Лесоповал» уже выпустил более 20 альбомов и останавливаться на этом не собирается.','Лесоповал avatar_artist.jpg','Лесоповал back_image_arist.jpg','#795548'),(28,'Воровайки','«Воровайки» —  это культовая российская группа, исполняющая шансон с хулиганским характером. Их песни – это истории о нелегкой судьбе, любви, дружбе и жизни без прикрас. Узнаваемые мелодии, проникновенные тексты и неподдельная искренность сделали \"Воровайки\" любимицами слушателей, ценящих настоящий уличный дух. Их творчество – это смесь лирики и дерзости, где каждая песня становится саундтреком к жизни людей, живущих по своим правилам.','Воровайки avatar_artist.jpg','Воровайки back_image_arist.jpg','#795548'),(29,'Александр Розенбаум','Александр Яковлевич Розенбаум — автор-исполнитель, артист с идеальной причёской, дипломами врача-терапевта и музыканта-аранжировщика. У него большой комплект наград — от премий «Золотой граммофон» и «Шансон года» до официальных званий «заслуженного» и «народного артиста Российской Федерации». Тематика песен Розенбаума — в диапазоне от военной поэзии и шансона до эстрадной любовной лирики, а выступает он нередко в одиночку, сольно, с гитарой наперевес, без поддержки оркестров и спецэффектов. Такой минимализм роднит Розенбаума с бардами, но ему всегда было тесно в палатке у костра — он выступал в составе различных ВИА, был худруком театра-студии имени самого себя, записывал альбомы с джазовыми и рок-музыкантами. Популярность пришла к Розенбауму благодаря лихим куплетам вроде «Гоп-стоп», надрывным афганским балладам («В горах Афгани», «Караван») и, конечно, нежному романсу «Вальс-бостон».','Александр Розенбаум avatar_artist.jpg','Александр Розенбаум back_image_arist.jpg','#F44336'),(30,'Владимир Кузьмин','В 1976 году в ВИА «Надежда» появился молодой мультиинструменталист, одинаково хорошо играющий на флейте, скрипке и гитаре. Начать петь юноше посоветовал вокалист ансамбля, артист Игорь Иванов — возможно, если бы не эта подсказка, Владимир Кузьмин выбрал бы в качестве любимого инструмента не гитару, а, например, флейту. Но с флейтой петь неудобно. В «Надежде», впрочем, петь Кузьмину не давали. Он ушёл в «Самоцветы» — и здесь не сложилось. Основал группу «Карнавал» на пару с Александром Барыкиным — но тут статусом фронтмена приходилось делиться. Наконец, в 1982 году Кузьмин оказался в группе «Динамик», это был ироничный блюз-рок-бэнд с матёрыми профессиональными музыкантами. Коллектив в первозданном виде просуществовал всего год, затем «Динамик» стал аккомпанирующим ансамблем Кузьмина. В 1986 году Владимир исполнил с Пугачёвой песню «Две звезды», и прима забрала его в свою группу. Через год Кузьмин решился на сольный альбом «Моя любовь». Тур с Пугачёвой помог его популярности, до конца восьмидесятых Владимир Кузьмин выпустил ещё четыре альбома, а затем уехал в Калифорнию. Итогом двух лет в Америке стали два официальных альбома и несколько ПМЖ для участников группы. Сам Кузьмин вернулся в Россию, где продолжил сольную карьеру — местные меломаны его помнили, с 1996 года он стал регулярно получать премии вроде «Песни года» и «Золотого граммофона», активно гастролировать по стране и записывать один за другим разноплановые альбомы. В таком чемпионском темпе Кузьмин работает по сей день.','Владимир Кузьмин avatar_artist.jpg','Владимир Кузьмин back_image_arist.jpg','#F44336'),(31,'Interpol','Interpol — американская группа, играющая в жанрах инди-рока и постпанка. Нью-йоркцев Interpol в последнюю очередь можно назвать бойз-бендом, однако история их начинается именно с одежды, точнее с … ботинок. Эту страницу своей истории «интерполовцы» афишировать не любят, но в качестве «легенды» она подходит как нельзя лучше. Особенно, если учесть, что Interpol - группа необычная, и стильные пиджаки и штиблеты отлично вписываются в имидж молодых интеллектуалов, играющих мрачную гитарную музыку с ощутимым налетом психоделии.','Interpol avatar_artist.jpg','Interpol back_image_arist.webp','#A5B82B'),(32,'Preoccupations','Preoccupations — канадская пост-панк-группа, образованная в Калгари, Альберта, в 2012 году под названием Viet Cong . Группа состоит из двух бывших участников рок-группы Women , вокалиста/басиста Мэтта Флегеля и барабанщика Майка Уоллеса, а также гитаристов Скотта Манро и Дэниела Кристиансена. Музыкальный стиль группы описывается как «лабиринтный пост-панк».','Preoccupations avatar_artist.jpg','Preoccupations back_image_arist.webp','#A5B82B'),(33,'The Garden','The Garden - американская пост-панк-группа из Ориндж Каунти, штат Калифорния, основанная в 2011 году братьями-близнецами Уайеттом и Флетчером Ширсами.','The Garden avatar_artist.jpg','The Garden back_image_arist.webp','#691717'),(34,'Twenty One Pilots','Дуэт из Коламбуса Twenty One Pilots играет довольно смелую и экспериментальную смесь инди и хип-хоп музыки, не забывая при этом использовать разнообразные электронные сэмплы. При создании своего саунда участники группы используют фортепиано, синтезаторы, барабаны, а иногда и укулеле, что ставит многих в тупик, при попытке отнести Twenty One Pilots к какому то определенному музыкальному жанру. Сами же музыканты, называя свой стиль, используют словосочетание \"шизофренический поп\" (schizoid pop).','TwentyOnePilots avatar_artist.jpg','Twenty One Pilots back_image_arist.jpeg','#DE2649'),(35,'Viagra Boys','Viagra Boys — это шестеро музыкантов из Стокгольма, которые встретились в тату-студии и решили основать пост-панк-группу. Их первый EP Consistency of Energy вышел в 2016 году. Но по-настоящему привлек внимание сингл с альбома Street Worms — Sports. Он определил особенное, драйвовое и неряшливое, звучание группы, а также основной посыл их творчества.','Viagra Boys avatar_artist.webp','Viagra Boys back_image_arist.webp','#691717');
