DROP TABLE IF EXISTS `concert`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `concert` (
  `id_concert` int NOT NULL AUTO_INCREMENT,
  `id_artist` int NOT NULL,
  `id_hall` int NOT NULL,
  `age_limit_concert` int DEFAULT NULL,
  `status_concert` enum('Событие планируется','Событие прошло','Событие отменено') NOT NULL,
  `date_start_concert` date NOT NULL,
  `time_start_concert` time NOT NULL,
  PRIMARY KEY (`id_concert`),
  KEY `id_artist` (`id_artist`),
  KEY `id_hall` (`id_hall`),
  CONSTRAINT `concert_ibfk_1` FOREIGN KEY (`id_artist`) REFERENCES `artist` (`id_artist`) ON DELETE CASCADE,
