INSERT INTO `hall` VALUES (1,'Сигнал','Современная многофункциональная площадка для концертов, выставок и корпоративных мероприятий. Известен профессиональным звуком, световым оборудованием и возможностью трансформации пространства под любые форматы.','Самара','Лесная','23'),(2,'Yalta','Мультиформатный клуб с живыми выступлениями отечественных и зарубежных артистов. Популярен тематическими вечеринками, фестивалями и динамичной атмосферой танцпола.','Калининград','Ялтинская','66'),(3,'Китайский лётчик Джао Да','Культовая площадка для андеграундной музыки и творческих экспериментов. Легендарное место с камерной атмосферой, где стартовали многие российские рок-группы.','Москва','Лубянский пр-д','25'),(4,'1930 Moscow','Исторический зал в здании бывшей кузницы. Сочетает индустриальный лофт-дизайн с современным техническим оснащением. Место для электронных вечеринок, арт-перформансов и фэшн-показов.','Москва','Партийный пер.','1'),(5,'Arena Hall / Aura Night Club','Два в одном: Arena Hall для масштабных концертов и Aura Night Club для клубных вечеринок. Известны VIP-зонами, тематическими декорациями и разноформатными событиями.','Воронеж','просп. Революции','56'),(6,'Свобода','Лофт-пространство с танцполом, баром и качественной акустикой. Проводит концерты, стендап-шоу и арт-инсталляции в стиле урбан-культуры.','Пермь','Краснофлотская','15а'),(7,'Свобода','Площадка-гигант с вместительным танцполом, зонами отдыха и LED-экранами. Фокус на электронной музыке, живых выступлениях и фестивалях с immersive-технологиями.','Екатеринбург','Черкасская','12'),(8,'Sound','Мультифункциональный клуб в стиле индастриал. Вмещает тысячи гостей на двух уровнях, предлагая VIP-ложи, ресторан и панорамные виды на залив.','Санкт-Петербург','Кожевенная линия','40б'),(9,'Reborn','Двухэтажный арт-хаб: бар с ретро-аркадами на первом уровне и концертная площадка с балконом на втором. Место для квартирников, инди-концертов и альтернативных вечеринок.','Казань','Право-Булачная','29'),(10,'Milo Concert Hall','Трёхуровневый зал с отдельными зонами для танцпола, VIP-гостей и банкетов. Известен индивидуальным обслуживанием и выступлениями топовых артистов.','Нижний Новгород','Родионова','4'),(11,'Machine Head','Клуб с камерной атмосферой и акцентом на живую музыку. Проводит акустические вечера, джазовые джем-сейшены и выступления локальных групп.','Саратов','Октябрьская','43'),(12,'Opera','Ночное заведение с современным интерьером и клубными вечеринками. Известно световыми шоу, выступлениями диджеев и атмосферой «non-stop».','Набережные челны','Московский просп.','140'),(13,'Ozz','Площадка для рок- и метал-концертов с мощной звуковой системой. Регулярно принимает андеграундные группы и организует тематические фестивали.','Челябинск','Энтузиастов','11'),(14,'Студия','Многофункциональное пространство в Оренбурге для творческих экспериментов. Здесь проходят акустические концерты, поэтические вечера, лекции и арт-проекты, объединяющие молодёжь и профессионалов.','Оренбург','Алтайская','5'),(15,'VK Stadium','Одна из крупнейших площадок Москвы, предназначенная для масштабных концертов, фестивалей и шоу-программ. Оснащена инновационным световым оборудованием и вместительным партером.','Москва','Ленинградский просп','80'),(16,'А2','Культовый питерский клуб с футуристическим дизайном. Популярен благодаря электронным вечеринкам, выступлениям топовых диджеев и интерактивным арт-инсталляциям.','Санкт-Петербург','просп. Медиков','3'),(17,'NEOMA','Креативный хаб в Петрозаводске, сочетающий концертную площадку, лофт и арт-галерею. Акцент на независимой музыке, авторских проектах и междисциплинарных коллаборациях.','Петрозаводск','Федосовой','30'),(18,'Zall Club','Главная танцевальная площадка Мурманска с разноформатными событиями: от техно-рейвов до кавер-групп. Интерьер в стиле индастриал подчёркивает урбанистическую эстетику.','Мурманск','Шмидта','43'),(19,'Ikra','Уютное пространство в Костроме с акцентом на альтернативную культуру. Проводит квартирники, акустические концерты и арт-выставки, создавая атмосферу творческого единения.','Кострома','2-я Волжская','4'),(20,'Нули','Эпицентр рок-культуры в Красноярске. Площадка славится энергичными концертами, стендап-вечерами и андеграундными фестивалями.','Красноярск','просп. им. Газеты Красноярский Рабочий','160'),(21,'Викинг','Универсальный зал в Омске для корпоративов, концертов и праздников. Отличается профессиональным техническим оснащением и возможностью трансформации пространства.','Омск','просп. Карла Маркса','18'),(22,'Kultura Concert Hall','Современный комплекс в Волгограде с залом на тысячи зрителей. Используется для международных гастролей, театральных премьер и мультимедийных проектов.','Волгоград','наб. 62-й Армии','6'),(23,'Дом учёных СО РАН','Интеллектуально-культурный центр Новосибирска. Помимо научных конференций, здесь проходят классические концерты, джазовые вечера и камерные спектакли.','Новосибирск','Морской просп.','23'),(24,'Кроп Арена','Многофункциональная арена в Краснодаре, адаптированная под концерты, спортивные соревнования и выставки. Вмещает до 10 000 зрителей.','Краснодар','Путевая','5'),(25,'Химволокно','Историческое здание в Твери, переоборудованное в арт-кластер. Здесь сочетаются индастриал-эстетика, экспериментальная музыка и мультижанровые фестивали.','Тверь','пл. Гагарина','1'),(26,'Дворец молодёжи','Ключевая площадка Петропавловска-Камчатского для молодёжных инициатив. Организует рок-фестивали, театральные лаборатории и образовательные форумы.','Петропавловск-камчатский','Атласова','24'),(27,'Концерт Холл (ex. Fesco Hall)','Крупнейшая площадка Владивостока с панорамным видом на бухту. Принимает мировых звёзд, ледовые шоу и масштабные конференции.','Владивосток','Верхнепортовая','38'),(28,'Городской дворец культуры','Классическая площадка Хабаровска с богатой историей. Здесь проходят симфонические концерты, балетные постановки и народные праздники.','Хабаровск','Ленина','85'),(29,'Концерт-холл (ex. Дикая лошадь)','Легендарное место в Иркутске для рок- и метал-концертов. Известен высокой энергетикой, андеграундной атмосферой и лояльной публикой.','Иркутск','Якоби','35'),(30,'ДК «Железнодорожник»','Культурный центр Тюмени с театрально-концертным залом. Проводит детские спектакли, народные гуляния и выступления эстрадных артистов.','Тюмень','Первомайская','55'),(31,'Dom печати','Арт-пространство в Уфе на базе бывшей типографии. Объединяет концерты инди-групп, фотовыставки и лекции о современном искусстве.','Уфа','50-летия Октября','19'),(32,'Nobel Concert Hall','Премиальная площадка в Ижевске с акустикой концертного уровня. Рассчитана на камерные выступления, джазовые импровизации и авангардные проекты.','Ижевск','Воткинское ш.','170'),(33,'Мёд','Атмосферный клуб в Ростове-на-Дону с живой музыкой и авторскими коктейлями. Частая площадка для джазовых вечеров и акустических кавер-групп.','Ростов-на-дону','Красноармейская','157'),(34,'Цех','Индустриальное пространство во Владимире для экспериментальных форматов. Проводит noise-концерты, перформансы и воркшопы по современному искусству.','Владимир','Дворянская','27'),(35,'Deep','Центр электронной культуры в Рязани. Знаменит тематическими вечеринками, выступлениями техно-диджеев и LED-инсталляциями.','Рязань','Завражнова','4'),(36,'Face Club','Тусовочное место Томска с танцполом, VIP-ложами и баром. Акцент на поп- и хаус-музыке, а также ежегодных тематических фестивалях.','Томск','Красноармейская','120'),(37,'Дворец «Губернаторский»','Элитная площадка Ульяновска для оперных постановок, симфонических оркестров и государственных торжеств. Интерьер в классическом стиле.','Ульяновск','Дворцовая','2'),(38,'Киноконцертный зал «Пенза»','Многофункциональный комплекс с кинозалом и сценой для мюзиклов. Популярен семейными мероприятиями и ретро-концертами.','Пенза','Бакунина','147'),(39,'Азот','Молодёжный центр Новомосковска для локальных групп и начинающих артистов. Проводит открытые микрофоны, рок-баттлы и мастер-классы.','Новомосковск','Куйбышева','15'),(40,'Музыкальный театр','Площадка, специализирующаяся на опереттах, мюзиклах и камерных концертах. Современное оборудование и акустика делают её идеальной для вокальных выступлений и театральных экспериментов.','Иваново','Пушкина','2'),(41,'Концертно-зрелищный центр «Миллениум»','Крупнейший зал региона, принимающий международные шоу, ледовые спектакли и гастроли звёзд эстрады. Известен вращающейся сценой и LED-экранами.','Ярославль','Которосльная наб.','53'),(42,'Дворец культуры им. Гагарина','Центр традиционной культуры с народными фестивалями, хоровыми концертами и ремесленными ярмарками. Сохраняет дух советской эпохи в архитектуре и программах.','Сергиев посад','просп. Красной Армии','185'),(43,'СРК «Арена»','Многофункциональный комплекс для спортивных событий, рок-концертов и выставок. Вместительный партер и модульная система сцены позволяют адаптировать пространство под любые форматы.','Кемерово','Гагарина','124'),(44,'Титов-Арена','Современная площадка с акцентом на поп- и рок-музыку. Известна масштабными световыми шоу и выступлениями российских топ-артистов.','Барнаул','Социалистический просп.','93'),(45,'Дворец искусств «Нефтяник»','Премиальный зал для оперных постановок, симфонических оркестров и гала-концертов. Интерьер сочетает классику и элементы северного модерна.','Сургут','Югорский тракт','5'),(46,'Grand Arena Ostrova','Арена для спортивно-музыкальных гибридных событий. Часто принимает чемпионаты, K-pop вечеринки и фестивали уличной культуры.','Благовещенск','Мухина','114'),(47,'Городской дворец культуры','Площадка для семейных мероприятий: детских спектаклей, танцевальных конкурсов и ретро-вечеров. Отличается камерной атмосферой.','Обнинск','просп. Ленина','126'),(48,'Дворец детского творчества','Креативное пространство для юных талантов. Проводит музыкальные конкурсы, театральные студии и интерактивные мастер-классы.','Ставрополь','Ленина','292'),(49,'Дружба','Уютный зал с акцентом на локальную культуру. Место для акустических концертов, поэтических чтений и вечеров авторской песни.','Чехов','Чехова','45'),(50,'Maison','Клуб в стиле лофт с электронными вечеринками и арт-перформансами. Известен минималистичным дизайном и экспериментальными проектами.','Тольяти','Юбилейная','40'),(51,'КРК «Мегаполис»','Развлекательный комплекс с кинотеатром, концертным залом и фуд-зоной. Популярен поп-концертами и комедийными шоу.','Липецк','Московская','75'),(52,'Руки Вверх! Бар','Ночное заведение в стиле 2000-х с тематическими вечеринками, кавер-группами и дискотеками. Ностальгическая атмосфера и танцевальные хиты.','Нереповец','Леднева','4'),(53,'М33','Культовый клуб с индустриальным дизайном. Проводит концерты альтернативных групп, стендап-выступления и квир-вечеринки.','Архангельск','Московский просп,','33'),(54,'Gaudi','Арт-пространство, вдохновлённое работами Гауди. Организует джазовые джем-сейшены, арт-базары и кинопоказы под открытым небом.','Киров','Володарского','103'),(55,'Yakutsk City Hall','Престижная площадка для официальных мероприятий, этнических фестивалей и ледовых шоу. Сочетает современные технологии и традиционные якутские мотивы.','Якутск','Орджоникидзе','38'),(56,'Галерея Холл','Мультиформатный зал в стиле ар-деко. Проводит классические концерты, фотовыставки и гастрономические фестивали.','Южно-сахалинск','2-я Центральная','1'),(57,'ДК «Россия»','Историческое здание с театральной сценой и балконом. Место для оперетт, детских утренников и выступлений местных коллективов.','Серпухов','Советская','90'),(58,'ДК «Коломна»','Культурный центр с акцентом на народное творчество. Известен фольклорными фестивалями, хоровыми концертами и реконструкциями.','Коломна','Окский просп.','17'),(59,'Городской концертный зал','Площадка для симфонических оркестров, хоровых коллективов и органной музыки. Акустика зала признана одной из лучших в регионе.','Тула','Советская','2'),(60,'Цирк','Не только цирковые представления, но и концерты под куполом. Уникальное пространство с возможностью воздушных трюков и 3D-проекций.','Новокузнецк','Кирова','70'),(61,'Физкультурно-спортивный комплекс','Гибридная арена для спортивных шоу, этнических фестивалей и рок-концертов. Известен масштабными декорациями.','Улан-удэ','Рылеева','2'),(62,'Филармония им. Олега Лундстрема','Джазовая мекка Сибири. Проводит биг-бэнд концерты, мастер-классы и международные джазовые фестивали.','Чита','Бутина','51'),(63,'Акрон','Индустриальный клуб в здании бывшего завода. Место для метал-концертов, рейвов и арт-инсталляций с неоновым освещением.','Великий новгород','Ломоносова','22'),(64,'Городской дворец культуры','Площадка для массовых мероприятий: от свадебных шоу до рэп-баттлов. Гибкая система зонирования и современный звук.','Стерлитамак','просп. Октября','35'),(65,'ДК им. XXX-летия Победы','Патриотический центр с военно-историческими реконструкциями, оркестровыми концертами и кинопоказами военной тематики.','Цошкар-ола','Первомайская','109'),(66,'Октябрь','Камерный зал для интеллектуальных мероприятий: лекций, камерной музыки и литературных вечеров. Интерьер в стиле советского модернизма.','Дубна','Космонавтов','1'),(67,'Филармония','Классическая площадка с органом и хоровой капеллой. Регулярные выступления гастролирующих симфонических оркестров и вокальных ансамблей.','Калуга','Ленина','60'),(68,'Дворец культуры','Архитектурный памятник с театральной сценой и кинозалом. Проводит кинофестивали, краеведческие лекции и джазовые концерты.','Выборг','Советская','16'),(69,'Зимний театр','Элитная площадка для оперных гастролей, балетных трупп и джазовых звёзд. Известен морскими пейзажами из окон зрительного зала.','Сочи','Театральная','2'),(70,'КДЦ «Октябрь»','Культурный хаб с вращающейся сценой и ледовой ареной. Место для ледовых мюзиклов, этнических фестивалей и конференций.','Ханты-мансийск','Дзержинского','7'),(71,'Городской дом культуры','Центр локальной культуры с народными ансамблями, театральными студиями и молодёжными рок-группами.','Ишим','Привокзальная','17'),(72,'Зимний театр','Историческое здание с зимним садом внутри. Проводит камерные концерты, литературные чтения и выставки местных художников.','Орехово-Зуево','Бугрова','5'),(73,'Дворец культуры БМЗ','Индустриальный гигант с залом на 2000 мест. Известен метал-фестивалями, театральными экспериментами и выставками промышленного искусства.','Брянск','Майской Стачки','6');
/*!40000 ALTER TABLE `hall` ENABLE KEYS */;
UNLOCK TABLES;

--
-- Table structure for table `notification`
--

DROP TABLE IF EXISTS `notification`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `notification` (
  `id_notification` int NOT NULL AUTO_INCREMENT,
  `id_user` int NOT NULL,
  `id_artist` int NOT NULL,
  `id_concert` int NOT NULL,
  `message_notification` text NOT NULL,
  `is_read` tinyint(1) DEFAULT '0',
  `date_notification` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_notification`),
  KEY `id_user` (`id_user`),
  KEY `id_artist` (`id_artist`),
  KEY `id_concert` (`id_concert`),
  CONSTRAINT `notification_ibfk_1` FOREIGN KEY (`id_user`) REFERENCES `user` (`id_user`) ON DELETE CASCADE,
  CONSTRAINT `notification_ibfk_2` FOREIGN KEY (`id_artist`) REFERENCES `artist` (`id_artist`) ON DELETE CASCADE,
  CONSTRAINT `notification_ibfk_3` FOREIGN KEY (`id_concert`) REFERENCES `concert` (`id_concert`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=41 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `notification`
--

