  `id_user` int NOT NULL,
  `id_section` int NOT NULL,
  `row_ticket` int DEFAULT NULL,
  `seat_ticket` int DEFAULT NULL,
  `status_ticket` enum('Активен','Использован','Возвращен') NOT NULL,
  `purchase_date_ticket` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `card_number_ticket` char(16) NOT NULL,
  PRIMARY KEY (`id_ticket`),
  KEY `id_concert` (`id_concert`),
  KEY `id_user` (`id_user`),
  KEY `id_section` (`id_section`),
  CONSTRAINT `ticket_ibfk_1` FOREIGN KEY (`id_concert`) REFERENCES `concert` (`id_concert`) ON DELETE CASCADE,
  CONSTRAINT `ticket_ibfk_2` FOREIGN KEY (`id_user`) REFERENCES `user` (`id_user`) ON DELETE CASCADE,
  CONSTRAINT `ticket_ibfk_3` FOREIGN KEY (`id_section`) REFERENCES `section` (`id_section`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=113 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
