CREATE TABLE `user` (
  `id_user` int NOT NULL AUTO_INCREMENT,
  `id_role` int NOT NULL,
  `first_name_user` varchar(50) NOT NULL,
  `last_name_user` varchar(50) NOT NULL,
  `birth_date_user` date NOT NULL,
  `login_user` varchar(50) NOT NULL,
  `email_user` varchar(100) NOT NULL,
  `city_user` varchar(50) DEFAULT NULL,
  `password_hash_user` text NOT NULL,
  `password_salt_user` text NOT NULL,
  PRIMARY KEY (`id_user`),
  UNIQUE KEY `login_user` (`login_user`),
  UNIQUE KEY `email_user` (`email_user`),
  KEY `id_role` (`id_role`),
  CONSTRAINT `user_ibfk_1` FOREIGN KEY (`id_role`) REFERENCES `role` (`id_role`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
